{
  "document_type": "lease",
  "lessor": "Bozhou Fengyi Chinese Medicine Development and Research Institute",
  "lessee": "Anhui Xuelingxian Pharmaceutical Co., Ltd.",
  "premises_address": "East Liuge Village, Weiwu Road, Bozhou",
  "area": {
    "value": 10000,
    "unit": "sqm"
  },
  "start_date": "2008-08-01",
  "end_date": "2023-07-31",
  "rent": {
    "amount": 1200000,
    "currency": "CNY",
    "period": "year"
  },
  "indexation": "none",
  "red_flags": [
    {
      "type": "tenant_break_option",
      "quote": "Party B has the priority to lease the house after the contract expires, and it can extend the lease term with negotiation of Party A if it cannot find the house promptly after the contract expires."
    },
    {
      "type": "tenant_break_option",
      "quote": "Party B can decorate the house without affecting the house structure, but the scale, scope, process and materials shall be approved by Party A, and then the construction work can be carried out."
    },
    {
      "type": "tenant_break_option",
      "quote": "If Party A transfers the house ownership to the third party according to the legal procedures, this contract continues to take effect to the new house owner without the agreement."
    },
    {
      "type": "tenant_break_option",
      "quote": "Party B shall get the approval of Party A if it intends to exchange the house with others, and Party A shall support the reasonable demand of Party B."
    },
    {
      "type": "tenant_break_option",
      "quote": "If the contract is terminated owing to the above reasons, the rent will be calculated by the actual using time, and it will refund the difference."
    },
    {
      "type": "tenant_break_option",
      "quote": "The two parties shall not take the responsibility for each other if they have the loss that the house is removed or rebuilt owing to the demand of municipal construction."
    },
    {
      "type": "tenant_break_option",
      "quote": "The two parties take no responsibilities if the house is damaged or Party B has loss owing to the force majeure."
    }
  ]
}
